<?php declare(strict_types=1);$minute=$minutesUi['minute'];$minuteId=$minute['id'];?>
<a class="minutes-back" href="<?=e($minutesUrl())?>">← <?=e($minutesText('Alle Protokolle'))?></a>
<article class="card minutes-reader" data-minutes-reader><header><span class="minutes-state minutes-state-<?=e($minute['state'])?>"><?=e($minutesText($minutesStates[$minute['state']]))?></span><h2><?=e($minute['title'])?></h2><p><time datetime="<?=e($minute['meeting_on'])?>"><?=e(dateDe($minute['meeting_on']))?></time> · <?=e($minutesText($minute['source_kind']==='pdf'?'PDF-Protokoll':'Protokolle'))?></p></header>
<?php if($minute['source_kind']==='pdf'):$previewUrl=$minutesUrl(['mid'=>$minuteId,'minute_file'=>$minuteId]);?><div class="minutes-document"><a class="btn btn-outline theme-secondary button" href="<?=e($previewUrl)?>"><?=icon('download')?> <?=e($minutesText('PDF herunterladen'))?></a></div><?php require __DIR__.'/../../Documents/pdf-viewer.php';?>
<?php else:?><div class="minutes-body"><?=$minute['body_html']?></div><button hidden type="button" class="btn btn-outline theme-secondary minutes-print" data-minutes-print><?=e($minutesText('Drucken / als PDF speichern'))?></button><?php endif?></article>
<?php if($minutesUi['lookup']):?><a class="btn btn-outline theme-secondary" href="<?=e($minutesUrl(['mid'=>$minuteId]))?>"><?=e($minutesText('Gespeichertes Protokoll öffnen'))?></a>
<?php elseif($minutesUi['write']):?><section class="card minutes-publishing"><div><h2><?=e($minutesText('Freigabe'))?></h2><p><?=e($minutesText(match($minute['state']){'published'=>'Dieses Protokoll können alle Mitglieder lesen. Ziehe die Freigabe zurück, um den Text oder die Datei zu bearbeiten.','draft'=>'Prüfe das Protokoll und gib es anschließend für die Mitglieder frei.',default=>'Dieses Protokoll ist archiviert und für Mitglieder nicht sichtbar.'}))?></p></div><div class="actions">
<?php if($minute['state']==='draft'):?><a class="btn btn-outline theme-secondary" href="<?=e($minutesUrl(['mid'=>$minuteId,'compose'=>'1']))?>"><?=e($minutesText('Bearbeiten'))?></a><?php endif?>
<?php foreach(match($minute['state']){'draft'=>['publish','archive'],'published'=>['withdraw','archive'],default=>['restore']}as$transition):?><form method="post" action="<?=e($minutesUrl(['mid'=>$minuteId]))?>" data-minutes-transition><?=csrf().hidden('action','minutes-transition').hidden('mid',$minuteId).hidden('version',$minute['version']).hidden('transition',$transition)?><label class="check"><input class="check" type="checkbox" name="confirm_transition" value="1" required> <?=e($minutesText($minutesConfirmLabels[$transition]))?></label><button class="btn btn-solid theme-primary"><?=e($minutesText($minutesTransitionLabels[$transition]))?></button></form><?php endforeach?></div></section><?php endif?>
